sys_ui_action.client_script_v2:
// A Function for the Refresh Holdings Data button on the trade table. On Click of Button it calls the Get Swift Data UI Action.
// A call is made to PositionDataForTrade which Glide Records to Trade Table and trigger 'el_custody_detail_position_ondemand' event.

function executePositionEvent() {

    var positionattributeSync = g_form.getValue("position_attribute_sync");
    var TradeSysId = g_form.getUniqueValue();
    var gajax = new GlideAjax("x_hsb11_mss_c_proc.getSwiftPosDataUIAction");
    gajax.addParam("sysparm_name", "PositionDataForTrade");
    gajax.addParam("sysparm_id", TradeSysId);
    gajax.addParam("sysparm_attribute_sync", positionattributeSync);

    gajax.getXMLAnswer(openList);
}

function openList(url) {
    if (url == "Attribute Sync is in progress") {
        g_form.addInfoMessage("Attribute Sync is already in progress");
    } 
	else if (url == "security account or security id is empty") {
        g_form.addErrorMessage("Holdings data sync was not completed due to missing security information.");
    }
}

sys_ui_action.script:
// Call SI to do api call for detail
// Updated as pat of MSSOTIQUBE-1902 and MSSOTIQUBE-2042.
function executePositionEvent() {
    var positionattributeSync = g_form.getValue("position_attribute_sync");
    var TradeSysId = g_form.getUniqueValue();
	var tablename = g_form.getTableName();

	if(tablename == 'x_hsb11_mss_c_proc_mss_custody_trade'){
    var gajax = new GlideAjax("x_hsb11_mss_custod.MSSCustodyOnDemandCallUtils");
    gajax.addParam("sysparm_name", "refreshPositionDataAPICall");
    gajax.addParam("sysparm_id", TradeSysId);
    gajax.addParam("sysparm_attribute_sync", positionattributeSync);
    gajax.getXMLAnswer(openList);
	}

 // For Passive Trade  

        if (tablename == 'x_hsb11_mss_c_proc_mss_custody_trade_passive') {
            var ondemand = new GlideAjax("x_hsb11_mss_custod.MSSCustodyOnDemandCallUtilsPassive");
            ondemand.addParam("sysparm_name", "refreshPositionDataAPICall");
            ondemand.addParam("sysparm_id", TradeSysId);
            ondemand.addParam("sysparm_attribute_sync", positionattributeSync);
            ondemand.getXMLAnswer(openList);
        }

}

function openList(url) {
    if (url == "Attribute Sync is in progress") {
        g_form.addInfoMessage("Attribute Sync is already in progress");
    } else if (url == "security account or security id is empty") {
        g_form.addErrorMessage("Holdings data sync was not completed due to missing security information.");
    }
}
